package org.eclipse.rdf4j.sail.lmdb.evaluation;

/**
 * Missing OPTIONAL cost components, separate from finite known-work counts and their proven bounds. The bounded mask
 * merges through quote transformations; it does not manufacture an expected count from absent width/locality facts.
 */
record OptionalCostCompleteness(long missing) {
	enum Component {
		BUILD_EPOCHS("build epochs and cache misses"),
		RETENTION("retention capacity and locality"),
		PAYLOAD_WIDTH("retained and encoded payload width"),
		SPILL("spill and demotion I/O"),
		INDEX("index construction and selectivity when indexed"),
		CODEC("lexical encoding and decoding");

		final String description;

		Component(String description) {
			this.description = description;
		}
	}

	static final OptionalCostCompleteness COMPLETE = new OptionalCostCompleteness(0L);
	static final OptionalCostCompleteness MATERIALIZATION = new OptionalCostCompleteness(
			(1L << Component.values().length) - 1L);

	OptionalCostCompleteness {
		if ((missing >>> Component.values().length) != 0L) {
			throw new IllegalArgumentException("Unknown OPTIONAL cost component");
		}
	}

	boolean incomplete() {
		return missing != 0L;
	}

	boolean incompleteFor(double demandedRows) {
		return demandedRows != 0D && incomplete();
	}

	OptionalCostCompleteness plus(OptionalCostCompleteness other) {
		return other.missing == 0L ? this : new OptionalCostCompleteness(missing | other.missing);
	}

	String reason() {
		StringBuilder result = new StringBuilder();
		for (Component component : Component.values()) {
			if ((missing & 1L << component.ordinal()) != 0L) {
				if (!result.isEmpty()) {
					result.append(", ");
				}
				result.append(component.description);
			}
		}
		return result.toString();
	}
}
